<script setup lang="ts">
import { ref, toRaw, watch } from 'vue'
import AppLink from './AppLink.vue'
import RaceIcon from './RaceIcon.vue'
import { useRaceSettings, raceLocalDate, raceIsoDate } from '../stores/race'
const { raceSettings, saveRaceSettings, raceStorageError } = useRaceSettings()
const draft = ref(structuredClone(toRaw(raceSettings.value)))
const dateTime = ref(raceLocalDate(draft.value.startsAt))
const error = ref('')
const saved = ref(false)
watch(raceSettings, value => { draft.value = structuredClone(toRaw(value)); dateTime.value = raceLocalDate(value.startsAt) })
function save() {
  error.value = ''; saved.value = false
  try { saveRaceSettings({ ...toRaw(draft.value), startsAt: raceIsoDate(dateTime.value) }); saved.value = true }
  catch (cause) { error.value = cause instanceof Error ? cause.message : 'Preteky sa nepodarilo uložiť.' }
}
function undo() { draft.value = structuredClone(toRaw(raceSettings.value)); dateTime.value = raceLocalDate(draft.value.startsAt); error.value = ''; saved.value = false }
function addSchedule() { if (draft.value.schedule.length < 20) draft.value.schedule.push({ id: crypto.randomUUID(), title: '', time: '', description: '' }) }
function moveSchedule(index: number, direction: number) { const list = draft.value.schedule; const item = list[index]; if (item && index + direction >= 0 && index + direction < list.length) { list.splice(index, 1); list.splice(index + direction, 0, item) } }
</script>
<template>
  <div><div class="flex flex-col justify-between gap-6 sm:flex-row sm:items-end"><div><p class="eyebrow text-race">Od nastavení až po štart</p><h1 class="heading-3 mt-3">Najbližšie preteky.</h1><p class="body-6 mt-3 text-ink/55">Uprav podujatie na hlavnej stránke aj stránke pretekov.</p></div><AppLink href="/preteky" class="dashboard-secondary self-start">Pozrieť stránku pretekov <RaceIcon name="external" /></AppLink></div><div class="demo-notice body-6 mt-6">Nastavenia sú uložené iba v tomto prehliadači. Uloženie nemení verejný web pre ostatných návštevníkov.</div><p v-if="raceStorageError" class="form-error mt-4" role="alert">{{ raceStorageError }}</p><p v-if="saved" class="dashboard-toast mt-6" role="status"><RaceIcon name="check" /> Preteky boli uložené. Hlavná stránka aj stránka podujatia zobrazujú nové údaje.</p>
    <form class="mt-8 grid gap-6" @submit.prevent="save">
      <section class="dashboard-card p-6 sm:p-8"><h2 class="heading-5">Základné informácie</h2><div class="mt-6 grid gap-4 md:grid-cols-2"><label class="form-label">Názov podujatia<input v-model="draft.name" name="race-name" class="form-input" required minlength="3" maxlength="120" /></label><label class="form-label">Séria alebo sezóna<input v-model="draft.series" name="race-series" class="form-input" maxlength="120" /></label><label class="form-label">Dátum a čas štartu<input v-model="dateTime" name="race-datetime" class="form-input" type="datetime-local" /><span class="caption-5 mt-2 block font-normal text-ink/55">Časové pásmo: Europe/Bratislava</span></label><label class="form-label">Miesto konania<input v-model="draft.location" name="race-location" class="form-input" required maxlength="200" /></label><label class="form-label md:col-span-2">Presná adresa vstupu alebo areálu<input v-model="draft.address" name="race-address" class="form-input" maxlength="300" placeholder="Doplň presnú adresu pre navigáciu" /></label><label class="form-label md:col-span-2">Popis podujatia<textarea v-model="draft.description" name="race-description" class="form-input min-h-32" maxlength="3000"></textarea></label></div><label class="body-6 mt-6 flex items-start gap-3"><input v-model="draft.confirmed" name="race-confirmed" type="checkbox" class="mt-1 h-4 w-4 accent-race" /><span>Termín je potvrdený. Zrušiť označenie ilustračného podujatia na stránke.</span></label></section>
      <section class="dashboard-card p-6 sm:p-8"><h2 class="heading-5">Registrácia a jazdci</h2><label class="body-6 mt-6 flex items-center gap-3"><input v-model="draft.registrationOpen" name="race-registration-open" type="checkbox" class="h-4 w-4 accent-race" /> Registrácia na preteky je otvorená</label><div class="mt-6 grid gap-4 md:grid-cols-2"><label class="form-label md:col-span-2">Odkaz na registráciu<input v-model="draft.registrationUrl" name="race-registration-url" class="form-input" type="url" placeholder="https://" :required="draft.registrationOpen" /></label><label class="form-label">Kategórie<textarea v-model="draft.categories" name="race-categories" class="form-input min-h-24" maxlength="2000" placeholder="Kategórie a prípadné vekové limity"></textarea></label><label class="form-label">Štartovné<input v-model="draft.riderFee" name="race-rider-fee" class="form-input" maxlength="300" placeholder="Cena a podmienky úhrady" /></label><label class="form-label md:col-span-2">Doklady, výstroj a technické požiadavky<textarea v-model="draft.requirements" name="race-requirements" class="form-input min-h-32" maxlength="3000"></textarea></label></div></section>
      <section class="dashboard-card p-6 sm:p-8"><div class="flex flex-wrap items-center justify-between gap-4"><h2 class="heading-5">Program dňa</h2><button type="button" class="dashboard-secondary" :disabled="draft.schedule.length >= 20" @click="addSchedule"><RaceIcon name="plus" /> Pridať bod programu</button></div><p class="body-6 mt-3 text-ink/55">Bez času sa zobrazí „Čas doplníme“. Poradie upravíš šípkami.</p><div class="mt-6 grid gap-4"><article v-for="(item, index) in draft.schedule" :key="item.id" class="rounded-sm border border-ink/15 p-4"><div class="mb-4 flex items-center justify-between gap-4"><span class="caption-3 text-race">Bod {{ index + 1 }}</span><div class="flex gap-2"><button type="button" class="pagination-button" :disabled="index === 0" :aria-label="'Presunúť bod ' + (index + 1) + ' vyššie'" @click="moveSchedule(index, -1)"><RaceIcon class="-rotate-90" /></button><button type="button" class="pagination-button" :disabled="index === draft.schedule.length - 1" :aria-label="'Presunúť bod ' + (index + 1) + ' nižšie'" @click="moveSchedule(index, 1)"><RaceIcon class="rotate-90" /></button><button type="button" class="button-sm px-2 text-race" :aria-label="'Odstrániť bod programu ' + (index + 1)" @click="draft.schedule.splice(index, 1)">Odstrániť</button></div></div><div class="grid gap-4 md:grid-cols-[160px_minmax(0,1fr)]"><label class="form-label">Čas<input v-model="item.time" class="form-input" type="time" /></label><label class="form-label">Názov<input v-model="item.title" class="form-input" required maxlength="160" /></label><label class="form-label md:col-span-2">Popis<textarea v-model="item.description" class="form-input" maxlength="1000"></textarea></label></div></article><p v-if="!draft.schedule.length" class="body-6 rounded-sm bg-ink/5 p-6 text-ink/55">Program je prázdny. Pridaj prvý bod alebo ho nechaj zatiaľ nezverejnený.</p></div></section>
      <section class="dashboard-card p-6 sm:p-8"><h2 class="heading-5">Diváci a kontakt</h2><div class="mt-6 grid gap-4 md:grid-cols-2"><label class="form-label">Vstupné pre divákov<input v-model="draft.spectatorFee" name="race-spectator-fee" class="form-input" maxlength="500" placeholder="Cena vstupného a prípadné zľavy" /></label><label class="form-label">Kontaktný email<input v-model="draft.contactEmail" name="race-contact-email" class="form-input" type="email" maxlength="180" /></label><label class="form-label">Kontaktný telefón<input v-model="draft.contactPhone" name="race-contact-phone" class="form-input" type="tel" maxlength="40" /></label><label class="form-label md:col-span-2">Parkovanie a zázemie<textarea v-model="draft.parking" name="race-parking" class="form-input min-h-24" maxlength="3000"></textarea></label></div></section>
      <p v-if="error" class="form-error" role="alert">{{ error }}</p><div class="flex flex-wrap justify-end gap-3"><button type="button" class="dashboard-secondary" @click="undo">Zahodiť neuložené zmeny</button><button type="submit" class="dashboard-primary"><RaceIcon name="check" /> Uložiť preteky</button></div>
    </form>
  </div>
</template>
